// Synthetic production-Web acceptance. Run against the ignored Rust fixture.
// Usage: node family_refresh_browser.mjs /absolute/evidence-directory
import {createRequire} from 'node:module';import {readFile,writeFile,mkdir} from 'node:fs/promises';
const require=createRequire(new URL('../../../../../web/package.json', import.meta.url));const {chromium}=require('playwright-core');
const dir=process.argv[2];if(!dir?.startsWith('/'))throw Error('absolute evidence directory required');await mkdir(dir,{recursive:true});const fixture=JSON.parse(await readFile(dir+'/fixture.json','utf8'));
const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const page=await browser.newPage({viewport:{width:1280,height:900}});const errors=[],checkpoints=[],posts=[];
page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(r.method()==='POST'&&r.url().includes('family-refreshes'))posts.push({url:r.url(),body:r.postDataJSON()})});
async function capture(name){await page.waitForTimeout(350);await page.screenshot({path:dir+'/'+name+'.png',fullPage:false});checkpoints.push({name,url:page.url(),overflow:await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1)});await writeFile(dir+'/checks.json',JSON.stringify({checkpoints,errors,posts},null,2));}
const root='/api/migrations/fub/family-refreshes';let bundle;
async function detail(){const r=await page.request.get('http://127.0.0.1:5198'+root+'/'+bundle);if(!r.ok())throw Error(await r.text());return r.json()}
async function ready(){for(let i=0;i<90;i++){let d=await detail();if(d.families.every(p=>['ready','completed','cancelled'].includes(p.state)))return d;await page.waitForTimeout(500)}throw Error('preparation timeout')}
async function selectBundle(id){bundle=id;await page.getByLabel('Original People import',{exact:true}).selectOption(fixture.parent);await page.getByLabel('Prepared refresh',{exact:true}).selectOption(bundle)}
try {
 await page.goto('http://127.0.0.1:5198/manage/migration');await page.locator('input[type=email]').fill(fixture.email);await page.locator('input[type=password]').fill(fixture.password);await page.getByRole('button',{name:'Sign in',exact:true}).click();await page.getByTestId('family-refresh').waitFor();
 const panel=page.getByTestId('family-refresh');await panel.getByLabel('Original People import',{exact:true}).selectOption(fixture.parent);await panel.getByLabel('Completed core comparison',{exact:true}).selectOption(fixture.report);await panel.getByLabel('Retained history capture',{exact:true}).selectOption(fixture.capture);
 let prior;try{prior=JSON.parse(await readFile(dir+'/flow.json','utf8'))}catch{};if(prior){bundle=prior.bundle;await panel.getByLabel('Prepared refresh',{exact:true}).selectOption(bundle)}else{const created=page.waitForResponse(r=>new URL(r.url()).pathname===root&&r.request().method()==='POST');await panel.getByRole('button',{name:'Prepare family refresh',exact:true}).click();bundle=(await(await created).json()).bundle_id;await writeFile(dir+'/flow.json',JSON.stringify({bundle}));}await ready();await page.waitForTimeout(2200);await capture('01-combined-initial-holds');
 for(const [family,name]of [['metadata','Tags and custom fields'],['activity','Notes and tasks']]){
  await panel.locator('[aria-label="Refresh family"]').getByRole('button',{name,exact:true}).click();await panel.locator('[aria-label="Refresh mappings"]').waitFor();await page.waitForTimeout(300);
  const selects=panel.locator('select[aria-label^="Mapping choice for"]');const n=await selects.count();
  for(let i=0;i<n;i++){
   const select=selects.nth(i);const row=select.locator('xpath=ancestor::li');const text=await row.innerText();
   if(family==='activity'&&text.includes('task kind'))await select.selectOption('kind:call');
   else if(family==='metadata'&&text.includes('New qualified tag'))await select.selectOption('create_matching');
   else {await row.getByRole('button',{name:'Choose existing destination',exact:true}).click();await panel.locator('[aria-label="Choose existing refresh destination"]').getByRole('button',{name:/^Choose /}).first().click();}
  }
  if(family==='activity')await panel.getByPlaceholder('America/Los_Angeles').fill('America/Los_Angeles');
  await panel.getByRole('button',{name:'Apply mapping choices',exact:true}).click();await ready();await page.waitForTimeout(2200);
 }
 let review=await detail();await writeFile(dir+'/review.json',JSON.stringify(review,null,2));if(!review.families.some(p=>Number(p.counts.tag_removals)>0))throw Error('missing explicit removals');if(!review.families.some(p=>Number(p.counts.held)>0))throw Error('missing local hold');await capture('02-ready-desktop');
 await page.setViewportSize({width:390,height:844});await capture('03-ready-mobile');await panel.getByLabel('I reviewed every selected family',{exact:false}).check();await panel.getByRole('button',{name:'Review confirmation',exact:true}).click();await page.getByRole('dialog').waitFor();await capture('04-mobile-confirmation');
 let lost=false;await page.route('**/api/migrations/fub/family-refreshes/*/confirm',async route=>{if(!lost){lost=true;await route.fetch();await route.abort('failed')}else await route.continue()});await page.getByRole('button',{name:'Apply reviewed refresh',exact:true}).click();await page.getByRole('button',{name:'Retry same confirmation',exact:true}).click();await page.unroute('**/api/migrations/fub/family-refreshes/*/confirm');
 const confirms=posts.filter(p=>p.url.endsWith('/confirm'));if(confirms.length!==2||JSON.stringify(confirms[0].body)!==JSON.stringify(confirms[1].body))throw Error('confirmation replay changed');await capture('05-confirmed-replayed');
 await panel.locator('[aria-label="Refresh family"]').getByRole('button',{name:'Notes and tasks',exact:true}).click();await panel.getByRole('button',{name:'Cancel Notes and tasks',exact:true}).click();await writeFile(dir+'/execute','1000');
 for(let i=0;i<120;i++){if((await detail()).bundle.state==='cancelled')break;await page.waitForTimeout(500)}await page.waitForTimeout(2200);await capture('06-partial-cancel');
 const remainderResponse=page.waitForResponse(r=>r.url().endsWith('/remainder')&&r.request().method()==='POST');await panel.getByRole('button',{name:'Prepare exact remainder',exact:true}).click();bundle=(await(await remainderResponse).json()).bundle_id;await writeFile(dir+'/execute','0');await ready();await page.waitForTimeout(2200);await capture('07-exact-remainder');
 await panel.getByLabel('I reviewed every selected family',{exact:false}).check();await panel.getByRole('button',{name:'Review confirmation',exact:true}).click();await page.getByRole('button',{name:'Apply reviewed refresh',exact:true}).click();await writeFile(dir+'/execute','2000');
 for(let i=0;i<120;i++){if((await detail()).bundle.state==='completed')break;await page.waitForTimeout(500)}if((await detail()).bundle.state!=='completed')throw Error('remainder not completed');await page.waitForTimeout(2200);await capture('08-completed-mobile');
 await page.reload();await selectBundle(bundle);await page.waitForTimeout(500);await capture('09-reloaded-mobile');await page.setViewportSize({width:1280,height:900});await capture('10-reloaded-desktop');
 await writeFile(dir+'/pause','1');await writeFile(dir+'/final.json',JSON.stringify(await detail(),null,2));
 await page.goto('http://127.0.0.1:5198/people/'+fixture.person);await page.getByLabel('History family',{exact:true}).selectOption('events');await page.locator('li').filter({hasText:'Corrected source record · version 2'}).getByRole('button',{name:/^Inspect fub_/}).first().click();await page.getByRole('button',{name:'Browse versions',exact:true}).click();await page.getByText('Version 2',{exact:true}).waitFor();await page.getByText('Version 1',{exact:true}).waitFor();await page.getByText('Version 1',{exact:true}).scrollIntoViewIfNeeded();await capture('11-history-versions-desktop');await page.setViewportSize({width:390,height:844});await page.getByText('Version 1',{exact:true}).scrollIntoViewIfNeeded();await capture('12-history-versions-mobile');await page.getByRole('button',{name:'Close metadata',exact:true}).click();
 const logout=page.getByRole('button',{name:/sign out|log out/i});if(!await logout.count())throw Error('logout missing');{await logout.first().click();await page.locator('input[type=email]').waitFor();if(await page.getByTestId('family-refresh').count())throw Error('private panel survived logout');await capture('13-private-cleared')}
 if(errors.length||checkpoints.some(c=>c.overflow))throw Error('browser errors or overflow');await writeFile(dir+'/checks.json',JSON.stringify({success:true,checkpoints,errors,posts},null,2));console.log(JSON.stringify({success:true,checkpoints:checkpoints.length,errors}));
} catch(e){await writeFile(dir+'/failure.txt',String(e)+'\n'+await page.locator('body').innerText());await capture('failure');throw e}finally{await browser.close()}
